if(typeof window==='undefined'){self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',(e)=>e.waitUntil(self.clients.claim()));self.addEventListener('message',(ev)=>{if(ev.data&&ev.data.type==='deregister'){self.registration.unregister().then(()=>{self.clients.matchAll().then((clients)=>{clients.forEach((client)=>client.navigate(client.url))})})}});self.addEventListener('fetch',function(event){if(event.request.cache==='only-if-cached'&&event.request.mode!=='same-origin'){return}event.respondWith(fetch(event.request).then(function(response){if(response.status===0){return response}const newHeaders=new Headers(response.headers);newHeaders.set('Cross-Origin-Embedder-Policy','require-corp');newHeaders.set('Cross-Origin-Opener-Policy','same-origin');newHeaders.set('Cross-Origin-Resource-Policy','cross-origin');return new Response(response.body,{status:response.status,statusText:response.statusText,headers:newHeaders})}))})}else{const coi={shouldRegister:()=>!window.crossOriginIsolated,register:()=>{const n=window.navigator;if(!n.serviceWorker){console.error('Service workers are not supported.');return}n.serviceWorker.register(window.document.currentScript.src).then((r)=>{console.log('COOP/COEP Service Worker registered.',r.scope);r.addEventListener('updatefound',()=>{window.location.reload()});if(r.active){console.log('COOP/COEP Service Worker is already active.')}else{console.log('Reloading page to make use of COOP/COEP Service Worker.');window.location.reload()}},(e)=>{console.error('COOP/COEP Service Worker failed to register:',e)})}};coi.shouldRegister()&&coi.register()}
